SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2014.Year, Станции2014.NUST, Станции2014.nr, Станции2014.E, Станции2014.EOTP, Станции2014.EURT, Станции2014.EUST, Станции2014.Q, Станции2014.TURT, Станции2014.TUST, Станции2014.B, Станции2014.GAZ, Доп_угли2014.gaz_prir, Доп_угли2014.gazpp, Станции2014.MAZUT, Доп_угли2014.maztop, Доп_угли2014.nft_proch, Доп_угли2014.disel, Станции2014.TORF, Станции2014.SLAN, Станции2014.ISK_GAZ, Доп_угли2014.domen_g, Доп_угли2014.koks_g, Доп_угли2014.prochgaz, Станции2014.PROCH, Доп_угли2014.tvproch, Доп_угли2014.szh_gaz, Доп_угли2014.inoe, Станции2014.UGOL, Станции2014.DON, Станции2014.PODM, Станции2014.PECH, Доп_угли2014.intin, Доп_угли2014.vork, Станции2014.ARKT, Станции2014.KUZN, Доп_угли2014.kuzngd, Доп_угли2014.kuznt, Доп_угли2014.kuznss, Доп_угли2014.kuznun, Станции2014.URAL, Доп_угли2014.sver, Доп_угли2014.chel, Доп_угли2014.kizel, Станции2014.BASHK, Станции2014.KAN, Доп_угли2014.nazar, Доп_угли2014.ibor, Доп_угли2014.berez, Доп_угли2014.per, Доп_угли2014.irbei, Доп_угли2014.kansk, Станции2014.TUNG, Доп_угли2014.jer, Доп_угли2014.karab, Станции2014.IRKUT, Доп_угли2014.azey, Доп_угли2014.mug, Доп_угли2014.cher, Станции2014.HAK, Станции2014.TUV, Станции2014.BUR, Доп_угли2014.gusin, Доп_угли2014.tugn, Доп_угли2014.okino, Станции2014.CHIT, Доп_угли2014.har, Доп_угли2014.urt, Доп_угли2014.tataur, Доп_угли2014.tarbag, Доп_угли2014.zab_kam, Станции2014.YAKUT, Доп_угли2014.neru, Доп_угли2014.zyryan, Доп_угли2014.pyak, Станции2014.AMUR, Доп_угли2014.rai, Доп_угли2014.erk, Доп_угли2014.ogodj, Станции2014.URG, Станции2014.USHUM, Станции2014.PRIM, Доп_угли2014.bikin, Доп_угли2014.razdol, Доп_угли2014.hankai, Станции2014.MAG, Станции2014.SAH, Станции2014.KAMCH, Станции2014.CHUKOT, Доп_угли2014.anad, Доп_угли2014.bering, Станции2014.KAZAH, Доп_угли2014.ekib, Доп_угли2014.maikub, Доп_угли2014.karag, Доп_угли2014.karajyra, Доп_угли2014.teniz, Станции2014.QOTR, Станции2014.SNK, Станции2014.EWTP, Станции2014.NT, Станции2014.OBOR, Станции2014.VED, Станции2014.OBL, Станции2014.DEP, Станции2014.OES, Станции2014.ER, Станции2014.NUMB1120, Имена_станций.Ведомство AS вед, IIf([вед]=1 Or [вед]=4,1,IIf([вед]=2 Or [вед]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, IIf([OBOR]=20 Or [OBOR]=90,"ГТУ",IIf([OBOR]=21 Or [OBOR]=91,"ПГУ",IIf([OBOR]=22,"Диз",IIf([OBOR]=23,"ГУБТ",IIf([OBOR]=24 Or [OBOR]=89,"ГПА","ПСУ"))))) AS тип, Станции2014.SNt, Имена_станций.n1 AS [мощность блока], IIf([B]>0,[gaz_prir]/[B]*100,0) AS dolya_gaz_prir, IIf([B]>0,[gazpp]/[B]*100,0) AS dolya_gazpp, IIf([B]>0,[UGOL]/[B]*100,0) AS dolya_ugol, IIf([B]>0,[MAZUT]/[B]*100,0) AS dolya_mazut, IIf([B]>0,[TORF]/[B]*100,0) AS dolya_torf, IIf([B]>0,[SLAN]/[B]*100,0) AS dolya_slan, IIf([B]>0,[PROCH]/[B]*100,0) AS dolya_proch, IIf([E]>0,[EWTP]/[E]*100,0) AS dolya_ewtp, IIf([Q]>0,[QOTR]/[Q]*100,0) AS dolya_qotr, IIf([B]>0 And [domen_g]>0,[domen_g]/[B]*100,0) AS dolya_domen_g, IIf([B]>0 And [koks_g]>0,[koks_g]/[B]*100,0) AS dolya_koks_g, IIf([B]>0 And [prochgaz]>0,[prochgaz]/[B]*100,0) AS dolya_prochgaz, IIf([B]>0,IIf([dolya_gaz_prir]>=50,"gaz_prir",IIf([dolya_gazpp]>=50,"gazpp",IIf([dolya_domen_g]>=50,"domen_g",IIf([dolya_koks_g]>=50,"koks_g",IIf([dolya_prochgaz]>=50,"prochgaz",IIf([dolya_ugol]>=50,"ugol",IIf([dolya_mazut]>=50,"neftetopl","prochee"))))))),"net topliva") AS nov_Belyaev, [EUST]/[B] AS [dolya topl na ee], [TUST]/[B] AS [dolya topl na q], Имена_областей.Terr_Belyaev, IIf([E]>0,([E]-[EOTP])/[E]*100,0) AS [%_sn], IIf([Имена_станций.BE]=9,"Пром.предпр.","Минэнерго") AS BLST_BE, IIf([Ведомство]=1,"Минэнерго","Пром.предпр.") AS BLST_V, IIf([вед]=1,"Минэнерго","Пром.предпр.") AS BLST_ved
FROM ((Имена_станций INNER JOIN (Имена_областей RIGHT JOIN (Имена_ОЭС INNER JOIN (Станции2014 LEFT JOIN Доп_угли2014 ON (Станции2014.YEAR = Доп_угли2014.YEAR) AND (Станции2014.NUMB1120 = Доп_угли2014.NUMB1120)) ON Имена_ОЭС.oes = Станции2014.OES) ON Имена_областей.OBL = Станции2014.OBL) ON Имена_станций.NUMB = Станции2014.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
